import {meshIdentity,validateMesh,validateOutline,fitMesh,meshedStroke} from './pattern-mesh.js';
import {warpTarget} from './pattern-warp.js';
// One disposable edit on the existing canvas; no source mutation before Apply.
export function initPatternMesh({$,canvas,getBoard,prepare,getView,blocked,closePopovers,status,preview,commit}){
 const panel=document.createElement('section');panel.id='mesh-controls';panel.className='popover';panel.hidden=true;panel.setAttribute('aria-label','Pattern mesh');panel.innerHTML='<h2>Pattern mesh</h2><p class="note">Position the image over your garment first. Draw its outline inside the image, then refine the nine points. Apply bakes pixels; Undo restores the original.</p><button id="mesh-outline" type="button">Draw fitting outline</button><label for="mesh-point">Control point</label><select id="mesh-point">'+Array.from({length:9},(_,i)=>'<option value="'+i+'">Point '+(i+1)+'</option>').join('')+'</select><label for="mesh-x">X %</label><input id="mesh-x" type="number" min="0" max="100" step="1"><label for="mesh-y">Y %</label><input id="mesh-y" type="number" min="0" max="100" step="1"><p id="mesh-error" role="alert"></p><div class="action-grid mesh-actions"><button id="mesh-reset" type="button">Reset mesh</button><button id="mesh-apply" type="button">Apply mesh</button><button id="mesh-cancel" type="button">Cancel</button></div>';
 document.body.append(panel);const ns='http://www.w3.org/2000/svg',overlay=document.createElementNS(ns,'svg');overlay.id='mesh-overlay';overlay.setAttribute('hidden','');overlay.setAttribute('aria-label','Pattern mesh controls');const lines=document.createElementNS(ns,'path');lines.setAttribute('class','mesh-grid');overlay.append(lines);const outlinePath=document.createElementNS(ns,'polyline');outlinePath.setAttribute('class','mesh-grid');overlay.append(outlinePath);const handles=[];for(let i=0;i<9;i++){const h=document.createElementNS(ns,'circle');h.setAttribute('r','12');h.dataset.point=i;h.setAttribute('tabindex','0');h.setAttribute('role','slider');h.setAttribute('aria-label','Mesh point '+(i+1));h.setAttribute('aria-valuemin','0');h.setAttribute('aria-valuemax','100');overlay.append(h);handles.push(h);}document.body.append(overlay);
 let draft=null,drag=null,tracing=false;const error=()=>document.getElementById('mesh-error'),apply=()=>document.getElementById('mesh-apply');
 function screen(p){const r=draft.source.raster,[a,b,c,d,e,f]=r.transform,v=getView();return [(a*p[0]*r.width+c*p[1]*r.height+e)*v.scale+v.x,(b*p[0]*r.width+d*p[1]*r.height+f)*v.scale+v.y];}
 function local(e){const rect=canvas.getBoundingClientRect(),v=getView(),x=(e.clientX-rect.left-v.x)/v.scale,y=(e.clientY-rect.top-v.y)/v.scale,r=draft.source.raster,[a,b,c,d,tx,ty]=r.transform,det=a*d-b*c;return [(d*(x-tx)-c*(y-ty))/det/r.width,(-b*(x-tx)+a*(y-ty))/det/r.height];}
 function sync(){if(!draft)return;const rect=canvas.getBoundingClientRect();overlay.style.left=rect.left+'px';overlay.style.top=rect.top+'px';overlay.style.width=rect.width+'px';overlay.style.height=rect.height+'px';overlay.setAttribute('viewBox','0 0 '+rect.width+' '+rect.height);const points=draft.mesh.map(screen);for(let i=0;i<9;i++){handles[i].setAttribute('cx',points[i][0]);handles[i].setAttribute('cy',points[i][1]);handles[i].setAttribute('aria-valuenow',Math.round(draft.mesh[i][0]*100));handles[i].setAttribute('aria-valuetext',Math.round(draft.mesh[i][0]*100)+' percent X, '+Math.round(draft.mesh[i][1]*100)+' percent Y');handles[i].style.visibility=tracing?'hidden':'visible';}lines.setAttribute('d',[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8]].map(ids=>ids.map((i,j)=>(j?'L':'M')+points[i].join(',')).join(' ')).join(' '));const poly=drag?.trace?drag.points:draft.outline;outlinePath.setAttribute('points',(poly||[]).map(screen).map(p=>p.join(',')).join(' '));const i=Number($('mesh-point').value);$('mesh-x').value=Math.round(draft.mesh[i][0]*10000)/100;$('mesh-y').value=Math.round(draft.mesh[i][1]*10000)/100;}
 function render(){if(!draft)return;sync();try{validateMesh(draft.mesh);const stroke=meshedStroke(draft.source,draft.mesh,draft.outline),b=structuredClone(draft.base);b.layers.find(l=>l.id===draft.layerId).strokes.find(s=>s.id===draft.id).raster=stroke.raster;preview(b);error().textContent='';apply().disabled=false;}catch(e){error().textContent=e.message;apply().disabled=true;preview(null);}}
 function cancel(){if(!draft)return;draft=null;drag=null;tracing=false;overlay.style.pointerEvents='none';overlay.setAttribute('hidden','');panel.hidden=true;preview(null);canvas.focus();}
 $('mesh-open').onclick=()=>{if(blocked())return;try{const target=prepare();closePopovers();draft={...target,mesh:meshIdentity(),outline:null};panel.hidden=false;overlay.removeAttribute('hidden');render();$('mesh-outline').focus();}catch(e){status(e.message,true);}};
 $('mesh-point').onchange=sync;for(const id of ['mesh-x','mesh-y'])$(id).onchange=()=>{if(!draft||drag)return;const i=Number($('mesh-point').value);draft.mesh[i]=[Number($('mesh-x').value)/100,Number($('mesh-y').value)/100];render();};
 $('mesh-outline').onclick=()=>{if(!draft)return;tracing=true;overlay.style.pointerEvents='auto';const b=structuredClone(draft.base);b.layers.find(l=>l.id===draft.layerId).strokes.find(s=>s.id===draft.id).opacity*=.25;preview(b);sync();status('Trace the garment inside the image · release to fit · Escape cancels');};
 overlay.onpointerdown=e=>{if(!draft||drag||e.button!==0)return;const i=e.target.dataset.point;if(!tracing&&i===undefined)return;e.preventDefault();const p=local(e);drag=tracing?{id:e.pointerId,trace:true,points:[p]}:{id:e.pointerId,index:Number(i),before:structuredClone(draft.mesh)};if(!tracing)$('mesh-point').value=i;overlay.setPointerCapture(e.pointerId);};
 overlay.onpointermove=e=>{if(!draft||drag?.id!==e.pointerId)return;e.preventDefault();const p=local(e);if(drag.trace){const last=drag.points.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])>.008){if(drag.points.length>=128){drag=null;tracing=false;overlay.style.pointerEvents='none';if(overlay.hasPointerCapture(e.pointerId))overlay.releasePointerCapture(e.pointerId);render();error().textContent='Outline point limit · draw a simpler outline';apply().disabled=true;return;}drag.points.push(p);}}else draft.mesh[drag.index]=p.map(v=>Math.max(0,Math.min(1,v)));sync();};
 function finish(e,cancelled){if(!draft||drag?.id!==e.pointerId)return;const done=drag;drag=null;tracing=false;overlay.style.pointerEvents='none';if(overlay.hasPointerCapture(e.pointerId))overlay.releasePointerCapture(e.pointerId);if(cancelled){if(done.before)draft.mesh=done.before;render();return;}try{if(done.trace){validateOutline(done.points);const mesh=fitMesh(done.points);draft.outline=done.points;draft.mesh=mesh;}render();status(done.trace?'Outline fitted · adjust mesh points, Apply or Cancel':'Mesh point updated · Apply or Cancel');}catch(err){render();error().textContent=err.message;apply().disabled=true;}}
 overlay.onpointerup=e=>finish(e,false);overlay.onpointercancel=e=>finish(e,true);overlay.onlostpointercapture=e=>{if(drag?.id===e.pointerId)finish(e,true);};
 for(const [i,h] of handles.entries())h.onkeydown=e=>{if(!draft||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.stopPropagation();const k=['ArrowLeft','ArrowRight'].includes(e.key)?0:1,delta=['ArrowLeft','ArrowUp'].includes(e.key)?-.01:.01;draft.mesh[i][k]=Math.max(0,Math.min(1,draft.mesh[i][k]+delta));$('mesh-point').value=i;render();};
 $('mesh-reset').onclick=()=>{if(!draft)return;drag=null;tracing=false;overlay.style.pointerEvents='none';draft.mesh=meshIdentity();draft.outline=null;render();};$('mesh-cancel').onclick=cancel;$('mesh-apply').onclick=()=>{if(!draft||drag||tracing)return;try{if(getBoard()!==draft.original)throw Error('Artwork changed · cancel and reopen');warpTarget(draft.base,draft.layerId,draft.id);const stroke=meshedStroke(draft.source,draft.mesh,draft.outline);commit(draft.layerId,draft.id,stroke,draft.original,draft.base);cancel();status('Mesh applied · Undo restores original pixels');}catch(e){error().textContent=e.message;apply().disabled=true;}};
 window.addEventListener('resize',sync);return {editing:()=>!!draft,key:e=>{if(!draft)return false;if(e.key==='Escape'){e.preventDefault();cancel();}return true;},cancel};
}
